-- Fill native Zero abilities only while the observed character and variant media are unchanged.

UPDATE character_appearance_variants SET abilities_json='[{"id":"GA_Female046_Skill","name":"Оценка и гравировка","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/46d11502e8d986fe3f62.webp","description":"Промах, враг раскрыт! Совершает 3 быстрых удара оружием, затем прыгает в воздух для зарядки и применяет Пушку эспера, нанося 1 удар урона космоса по области. Дополнительно наносит первому пораженному противнику, чей уровень ниже уровня Ноль, 1 удар урона космоса.\n\nОчерченная тонкими штрихами сюрреалистическая сцена возникает словно из ниоткуда…","attributes":[{"id":"parameter-0","label":"Множитель удара оружием","value":"1: 20 %+20 %+125.6 %+134.4 % · 2: 21.6 %+21.6 %+135.6 %+145.2 % · 3: 23.3 %+23.3 %+146.5 %+156.8 % · 4: 25.2 %+25.2 %+158.2 %+169.3 % · 5: 27.2 %+27.2 %+170.9 %+182.8 % · 6: 29.4 %+29.4 %+184.5 %+197.5 % · 7: 31.7 %+31.7 %+199.3 %+213.3 % · 8: 34.3 %+34.3 %+215.3 %+230.3 % · 9: 37 %+37 %+232.5 %+248.8 % · 10: 40 %+40 %+251.1 %+268.7 % · 11: 43.2 %+43.2 %+271.2 %+290.2 % · 12: 46.6 %+46.6 %+292.9 %+313.4 % · 13: 50.4 %+50.4 %+316.3 %+338.4 %"},{"id":"parameter-1","label":"Множитель доп. урона","value":"1: 200 % · 2: 200 % · 3: 200 % · 4: 200 % · 5: 200 % · 6: 200 % · 7: 200 % · 8: 200 % · 9: 200 % · 10: 200 % · 11: 200 % · 12: 200 % · 13: 200 %"}]},{"id":"GA_Female046_UltraSkill","name":"Деление на ноль","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/498d8117fd2f3573fbc1.webp","description":"Танцуя, я разрываю связи между Нексусами, что вижу лишь я. Наносит несколько ударов урона космоса по области.\n\nЯ чувствую нексус аномалии, связанный невидимыми, неслышимыми, неосязаемыми узами… Все они мгновенно разрубаются одним изящным ударом.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 132.7 % + 5.3 % *4 + 177.5 % + 168.6 % · 2: 143.3 % + 5.7 % *4 + 191.7 % + 182.1 % · 3: 154.8 % + 6.2 % *4 + 207 % + 196.7 % · 4: 167.2 % + 6.7 % *4 + 223.6 % + 212.4 % · 5: 180.5 % + 7.2 % *4 + 241.5 % + 229.4 % · 6: 195 % + 7.8 % *4 + 260.8 % + 247.7 % · 7: 210.6 % + 8.4 % *4 + 281.7 % + 267.5 % · 8: 227.4 % + 9.1 % *4 + 304.2 % + 289 % · 9: 245.6 % + 9.8 % *4 + 328.5 % + 312.1 % · 10: 265.3 % + 10.6 % *4 + 354.8 % + 337 % · 11: 286.5 % + 11.4 % *4 + 383.2 % + 364 % · 12: 309.4 % + 12.4 % *4 + 413.9 % + 393.1 % · 13: 334.2 % + 13.3 % *4 + 447 % + 424.6 %"}]},{"id":"GA_Female046_QTE","name":"Цветение разлома","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/a1241879288ff27fc6e0.webp","description":"Рассекая пространство, взрывает разлом, нанося 2 удара урона космоса по области.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 75.3 %+124.7 % · 2: 81.3 %+134.7 % · 3: 87.8 %+145.5 % · 4: 94.9 %+157.1 % · 5: 102.4 %+169.7 % · 6: 110.6 %+183.2 % · 7: 119.5 %+197.9 % · 8: 129.1 %+213.7 % · 9: 139.4 %+230.8 % · 10: 150.5 %+249.3 % · 11: 162.6 %+269.2 % · 12: 175.6 %+290.8 % · 13: 189.6 %+314 %"}]},{"id":"GA_Female046_Melee","name":"Оценка","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/9591f6ffcffdbe3b70ac.webp","description":"Базовая атака: Оценка: отделение\nНаполняет энергией свое оружие и проводит до 5 последовательных атак, нанося урон космоса.\n\nБазовая атака: Оценка: разрушение\nВзмахивает своим оружием в воздухе и пикирует, нанося 1 удар урона космоса по области при ударе. Урон увеличивается в зависимости от высоты падения (до 100 %).\n\nКритический контрудар: вспышка вдохновения\nСрабатывает при использовании Оценки: отделение после критического уклонения. Использует промах противника для контратаки, выполняя удар своим оружием, нанося 1 удар урона космоса по области и снижая разрушение.\n\nВзять в руки меч – единственный способ почувствовать себя хозяином положения.","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 23 % · 2: 24.8 % · 3: 26.8 % · 4: 29 % · 5: 31.3 % · 6: 33.8 % · 7: 36.5 % · 8: 39.4 % · 9: 42.6 % · 10: 46 % · 11: 49.7 % · 12: 53.6 % · 13: 57.9 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 22.4 %+25.9 % · 2: 24.2 %+28 % · 3: 26.1 %+30.2 % · 4: 28.2 %+32.6 % · 5: 30.5 %+35.2 % · 6: 32.9 %+38.1 % · 7: 35.5 %+41.1 % · 8: 38.4 %+44.4 % · 9: 41.5 %+47.9 % · 10: 44.8 %+51.8 % · 11: 48.4 %+55.9 % · 12: 52.2 %+60.4 % · 13: 56.4 %+65.2 %"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 37.9 %+6.4 %+38.5 % · 2: 40.9 %+6.9 %+41.6 % · 3: 44.2 %+7.5 %+44.9 % · 4: 47.7 %+8.1 %+48.5 % · 5: 51.6 %+8.7 %+52.4 % · 6: 55.7 %+9.4 %+56.6 % · 7: 60.1 %+10.2 %+61.1 % · 8: 65 %+11 %+66 % · 9: 70.2 %+11.8 %+71.3 % · 10: 75.8 %+12.8 %+77 % · 11: 81.8 %+13.8 %+83.1 % · 12: 88.4 %+14.9 %+89.8 % · 13: 95.4 %+16.1 %+96.9 %"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 15.4 %+99.7 % · 2: 16.6 %+107.7 % · 3: 18 %+116.3 % · 4: 19.4 %+125.6 % · 5: 21 %+135.6 % · 6: 22.6 %+146.5 % · 7: 24.4 %+158.2 % · 8: 26.4 %+170.9 % · 9: 28.5 %+184.5 % · 10: 30.8 %+199.3 % · 11: 33.2 %+215.2 % · 12: 35.9 %+232.5 % · 13: 38.8 %+251.1 %"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 68.3 % · 2: 73.8 % · 3: 79.7 % · 4: 86 % · 5: 92.9 % · 6: 100.4 % · 7: 108.4 % · 8: 117.1 % · 9: 126.4 % · 10: 136.5 % · 11: 147.5 % · 12: 159.3 % · 13: 172 %"},{"id":"parameter-5","label":"Множитель урона атаки в падении","value":"1: 65 % · 2: 70.2 % · 3: 75.8 % · 4: 81.9 % · 5: 88.4 % · 6: 95.5 % · 7: 103.1 % · 8: 111.4 % · 9: 120.3 % · 10: 129.9 % · 11: 140.3 % · 12: 151.6 % · 13: 163.7 %"},{"id":"parameter-7","label":"Множитель критического контрудара","value":"1: 150 % · 2: 162 % · 3: 175 % · 4: 189 % · 5: 204.1 % · 6: 220.4 % · 7: 238 % · 8: 257.1 % · 9: 277.6 % · 10: 299.9 % · 11: 323.8 % · 12: 349.7 % · 13: 377.7 %"}]},{"id":"GA_Female_Passive_2","name":"Восприятие аномалий","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/5ee8e7fb9bdfbb3aff17.webp","description":"Сверхспособность «Деление на ноль»: урон увеличивается на 25 %.\n\nСинхронизация нулевого чувства","attributes":[]},{"id":"GA_Female_Passive_1","name":"Оценщик","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/4196160bf74bdc68a0ee.webp","description":"Усиление зарядки: восстанавливает ОЗ в размере 50 % базовой атаки Ноль, когда активный персонаж получает энергию сверхспособности.\n\nКуда приведет меня эта способность читать и понимать аномалии?","attributes":[]},{"id":"City_Ability_palyer_01","name":"Пятизвездочный образец","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/f86210463f7747e5df8c.webp","description":"Если уровень связи равен 4 или ниже, подарки дают на 5 % больше симпатии.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Если уровень связи равен 4 или ниже, подарки дают на 5 % больше симпатии."},{"id":"city-1","label":"Уровень 2","value":"Если уровень связи равен 5 или ниже, подарки дают на 5 % больше симпатии."},{"id":"city-2","label":"Уровень 3","value":"Если уровень связи равен 6 или ниже, подарки дают на 5 % больше симпатии."},{"id":"city-3","label":"Уровень 4","value":"Если уровень связи равен 7 или ниже, подарки дают на 5 % больше симпатии."},{"id":"city-4","label":"Уровень 5","value":"Если уровень связи равен 8 или ниже, подарки дают на 5 % больше симпатии."}]}]'
      WHERE character_id='esper-zero' AND variant_id='1046' AND abilities_json='[]'
      AND name='Мужской вариант' AND json(skins_json)=json('[{"id":"Fashion_1046_rpg_level1","name":"Неприметный воин","imageUrl":"/nte-meta/game-assets/b1a6ede18c2c4caca341.webp","description":"Застегни верхнюю пуговицу, расправь воротник.\n\nТе, кто впервые отправляется в путь, должны научиться этому в первую очередь."},{"id":"Fashion_1046_0","name":"Начало истории","imageUrl":"/nte-meta/game-assets/d4e610bd9fce8d53dcd3.webp","description":"Чёткий, минималистичный силуэт, прекрасно подходящий для ежедневной работы."},{"id":"Fashion_1046_2","name":"Охотник в свободное время","imageUrl":"/nte-meta/game-assets/855589fe9fa980c7dc46.webp","description":"Игривый, но стильный многослойный наряд с броскими аксессуарами, подчёркивающий беспечный характер.\n\n«Охотник первого класса должен иметь первоклассное чувство стиля!»"},{"id":"Fashion_1046_swimsuit","name":"Безоблачное лето","imageUrl":"/nte-meta/game-assets/8cac25efa47a8dcf6028.webp","description":"Морской бриз уносит бумажный самолётик к далёким берегам. Что оставит после себя это лето?"},{"id":"Fashion_1046_rpg_level2","name":"Мастер клинка","imageUrl":"/nte-meta/game-assets/48d6bfa5f95e3587b6df.webp","description":"Ветер сохранит память о пути мечника."},{"id":"Fashion_1046_3","name":"Городской странник","imageUrl":"/nte-meta/game-assets/7fd16e0e51519b44c3cc.webp","description":"Лёгкий и облегающий костюм с простым и аккуратным кроем поможет легко слиться с толпой."},{"id":"Fashion_1046_rpg_level3","name":"Дни славы","imageUrl":"/nte-meta/game-assets/55c20fa1bc068b19e105.webp","description":"Увенчанная славой, долгая ночь наконец обретает свой свет."},{"id":"Fashion_1046_5","name":"Размышления о школе","imageUrl":"/nte-meta/game-assets/65f7575d63a82302ac5e.webp","description":"Элегантная академическая форма в сдержанных тонах с классическими узорами, подчеркивающая утончённую ауру отличника.\n\n«Хочешь вместе пойти на завтрашнюю вечеринку?»"},{"id":"Fashion_1046_4","name":"Нетрадиционная одежда","imageUrl":"/nte-meta/game-assets/12cac2ad698f6bf88eb3.webp","description":"Стандартная форма изолятора с хорошо сидящим кроем, комфортной тканью и яркими цветами. Вот бы можно было носить её как обычную одежду…"},{"id":"Fashion_1046_7","name":"Идеальный дуэт","imageUrl":"/nte-meta/game-assets/9ee2bb0b8dcf6f882de5.webp","description":"Безупречно сидящий гоночный костюм так же незаменим, как напарник рядом."},{"id":"Fashion_1046_6","name":"Уличный художник","imageUrl":"/nte-meta/game-assets/e3f6a0b904f6940d93ed.webp","description":"Игривый комплект с очаровательным детским комбинезоном, уникальными принтами, асимметричным дизайном и ярко выраженной индивидуальностью. Даже брызги краски выглядят на нём как часть принта."}]')
      AND json(voice_lines_json)=json('[{"id":"en-Play_Vo_Char_ZERO_M_DodgeCombo_002","title":"Серия критических уклонений II","language":"Английский","audioUrl":"/nte-meta/game-audio/283d5428f7c1aca6c557.ogg","sourceUrl":"","description":"Хм-м, не так уж сложно."},{"id":"ja-Play_Vo_Char_ZERO_M_TeammateDown_003","title":"Поражен товарищ по команде – Адлер","language":"Японский","audioUrl":"/nte-meta/game-audio/9221058ab3c16a2926f4.ogg","sourceUrl":"","description":"«Эйбон» никогда не сдаётся."},{"id":"ja-Play_Vo_Char_ZERO_M_windfall_001","title":"Неожиданная добыча I","language":"Японский","audioUrl":"/nte-meta/game-audio/8f0d0124fd4cf4dbb4e4.ogg","sourceUrl":"","description":"Спрячь это как следует."},{"id":"en-Play_Vo_Char_ZERO_M_QTE_001","title":"Атака на входе I","language":"Английский","audioUrl":"/nte-meta/game-audio/b0fbb53ed55434893992.ogg","sourceUrl":"","description":"Оценить… и разбить!"},{"id":"ja-Play_Vo_Char_ZERO_M_aoe_UI_001","title":"Сверхспособность I","language":"Японский","audioUrl":"/nte-meta/game-audio/b76db0a0e10e472c5e0b.ogg","sourceUrl":"","description":"Закончим это!"},{"id":"ja-Play_Vo_Char_ZERO_M_TeammateDown_001","title":"Поражен товарищ по команде – Хотори","language":"Японский","audioUrl":"/nte-meta/game-audio/cdd1dfdc5f5e5589f545.ogg","sourceUrl":"","description":"Оставь это вино… потом выпьешь."},{"id":"ja-Play_Vo_Char_ZERO_M_kill_002","title":"Убийство II","language":"Японский","audioUrl":"/nte-meta/game-audio/e97dc5e64bab38113530.ogg","sourceUrl":"","description":"Нексус, вот он."},{"id":"ja-Play_Vo_Char_ZERO_M_Mh_001","title":"Исцеление I","language":"Японский","audioUrl":"/nte-meta/game-audio/272412696aaf9576c1dc.ogg","sourceUrl":"","description":"Спасибо за поддержку."},{"id":"en-Play_Vo_Char_ZERO_M_deploy_002","title":"Отправка I","language":"Английский","audioUrl":"/nte-meta/game-audio/a85ad8fa0bf067dc7be9.ogg","sourceUrl":"","description":"Ясно, предоставь это мне."},{"id":"ja-Play_Vo_Char_ZERO_M_DodgeCombo_001","title":"Серия